import{_ as p,a0 as i,w as s,s as a,ao as l,I as r,x as o,a1 as e,A as u}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const c=JSON.parse('{"title":"每日Ubuntu小技巧——瞭解Root帳號 | LCTT x X-CMD","titleTemplate":false,"description":"每日Ubuntu小技巧——瞭解Root帳號 | LCTT (201310) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"每日Ubuntu小技巧——瞭解Root帳號 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"每日Ubuntu小技巧——瞭解Root帳號 | LCTT (201310) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201310/Daily Ubuntu Tips–Knowing About The Root Account","title":"每日Ubuntu小技巧——瞭解Root帳號","tag":"201310","desc":""},"relativePath":"201310/Daily Ubuntu Tips–Knowing About The Root Account.md","filePath":"[post].md"}'),d={name:"201310/Daily Ubuntu Tips–Knowing About The Root Account.md"};function g(b,t,T,m,f,w){const n=i("Link");return s(),a("div",null,[t[11]||(t[11]=l(`<h1 id="每日ubuntu小技巧——瞭解root帳號" tabindex="-1">每日Ubuntu小技巧——瞭解Root帳號 <a class="header-anchor" href="#每日ubuntu小技巧——瞭解root帳號" aria-label="Permalink to “每日Ubuntu小技巧——瞭解Root帳號”">​</a></h1><p>對於想了解Root帳號的Ubuntu新手，這裏有一個簡短的文章會讓你對root賬號和如何使用及為什麼使用root賬號有些清楚的認識。如你所見，每個版本的Ubuntu都會帶一個root賬號。</p><p>root賬號也被稱作管理員賬號。你可以將root賬號看作是有着同上帝一樣的權力的賬號。它可以刪除任何文件，任何目錄並對系統做出任何修改。root賬號的權限是無限制的。</p><p>由於root賬號過於強大，系統會自動地產生一個密碼串，該密碼串在系統上不可能通過加密來匹配到，如此一來用户就不能使用root帳號登入系統了。相對直接用root帳號登錄，Ubuntu更支持用户使用sudo命令。</p><p>sudo命令可以使已獲得授權的用户在不知道root帳號的密碼也不使用root帳號的情況下，通過使用自己的密碼暫時提升自己的權限。</p><p>如果你因為一些其它原因仍然想要使用root帳號並用它登錄系統，很簡單，給它設置一個密碼就可以了。這樣就可以使能root帳號了。</p><pre><code>sudo passwd
</code></pre><p>上面的命令可以激活root帳號，但是想要用root帳號登錄系統，你還必須打開被Ubuntu禁用的手動登錄功能。手動登錄功能允許用户輸入帳號和相應的登錄密碼而不僅僅是從登錄界面選擇一個帳號登錄。</p><p>要在<strong>Ubuntu 13.10</strong>中打開手動登錄選項，你可以運行下面的命令</p><pre><code>sudo gedit /etc/lightdm/lightdm.conf.d/50-unity-greeter.conf
</code></pre><p>然後如圖所示添加下面這一行文字</p><pre><code>greeter-show-manual-login=true
</code></pre><p><img src="" alt=""></p><p>保存並重啓電腦。</p><p>對於較早版本的Ubuntu，你可以在另外一個位置，即<strong>/etc/lightdm</strong>目錄下找到這個配置文件。文件名可能叫<strong>lightdm.conf</strong>。</p><p>修改完後，在登錄界面，你就可以輸入root帳號和相應的密碼然後登錄系統了。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/09/ubuntu-root-logon-1.png" alt=""></p><p>如果你想鎖定/禁用root帳號，使用下面的命令</p><pre><code>sudo passwd -l root
</code></pre><p>使用愉快！</p><hr>`,21)),r("p",null,[t[1]||(t[1]=o("via: ",-1)),e(n,{href:"http://www.liberiangeek.net/2013/09/daily-ubuntu-tipsknowing-root-account/"},{default:u(()=>[...t[0]||(t[0]=[o("http://www.liberiangeek.net/2013/09/daily-ubuntu-tipsknowing-root-account/",-1)])]),_:1})]),r("p",null,[t[4]||(t[4]=o("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:u(()=>[...t[2]||(t[2]=[o("LCTT",-1)])]),_:1}),t[5]||(t[5]=o(" 原創翻譯，",-1)),e(n,{href:"http://linux.cn/"},{default:u(()=>[...t[3]||(t[3]=[o("Linux中國",-1)])]),_:1}),t[6]||(t[6]=o(" 榮譽推出",-1))]),r("p",null,[t[9]||(t[9]=o("譯者：",-1)),e(n,{href:"https://github.com/Linchenguang"},{default:u(()=>[...t[7]||(t[7]=[o("Linchenguang",-1)])]),_:1}),t[10]||(t[10]=o(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:u(()=>[...t[8]||(t[8]=[o("wxy",-1)])]),_:1})])])}const h=p(d,[["render",g]]);export{c as __pageData,h as default};
